    seen = set()
    target = case['target']
    for value in case['nums']:
        if target - value in seen:
            return True
        seen.add(value)
    return False

def solve_case(case):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for char in case['s']:
        if char in '([{':
            stack.append(char)
        elif not stack or stack.pop() != pairs[char]:
            return False
    return not stack

